class Solution {
    static const int SIZE = 1001;
    static const int OFFSET = 500;

    int grid[SIZE][SIZE] = {};

    const int dx[4] = {-1, 1, 0, 0};
    const int dy[4] = {0, 0, -1, 1};

    const char dir[4] = {'U', 'D', 'L', 'R'};
    const char back[4] = {'D', 'U', 'R', 'L'};

    struct Frame {
        int x, y;
        int nextDir;
        int returnDir;
    };

public:
    int findShortestPath(GridMaster &master) {
        memset(grid, 0, sizeof(grid));

        int sx = OFFSET;
        int sy = OFFSET;

        int tx = -1, ty = -1;

        // Phase 1: Iterative DFS to discover grid.
        stack<Frame> st;

        st.push({sx, sy, 0, -1});
        grid[sx][sy] = 1;

        if (master.isTarget()) {
            tx = sx;
            ty = sy;
        }

        while (!st.empty()) {
            Frame &f = st.top();

            if (f.nextDir == 4) {
                int returnDir = f.returnDir;
                st.pop();

                if (returnDir != -1) {
                    master.move(back[returnDir]);
                }

                continue;
            }

            int d = f.nextDir++;

            int nx = f.x + dx[d];
            int ny = f.y + dy[d];

            if (nx < 0 || ny < 0 ||
                nx >= SIZE || ny >= SIZE)
                continue;

            if (grid[nx][ny] != 0)
                continue;

            if (!master.canMove(dir[d])) {
                grid[nx][ny] = -1;
                continue;
            }

            master.move(dir[d]);

            grid[nx][ny] = 1;

            if (master.isTarget()) {
                tx = nx;
                ty = ny;
            }

            st.push({nx, ny, 0, d});
        }

        if (tx == -1)
            return -1;

        // Phase 2: BFS to find shortest path.
        queue<pair<int, int>> q;

        q.push({sx, sy});
        grid[sx][sy] = 2;

        int distance = 0;

        while (!q.empty()) {
            int n = q.size();

            while (n--) {
                pair<int, int> p = q.front();
                q.pop();

                int x = p.first;
                int y = p.second;

                if (x == tx && y == ty)
                    return distance;

                for (int d = 0; d < 4; ++d) {
                    int nx = x + dx[d];
                    int ny = y + dy[d];

                    if (nx < 0 || ny < 0 ||
                        nx >= SIZE || ny >= SIZE)
                        continue;

                    if (grid[nx][ny] != 1)
                        continue;

                    grid[nx][ny] = 2;
                    q.push({nx, ny});
                }
            }

            ++distance;
        }

        return -1;
    }
};
